import json

def transform_diamond_v7(grid):
    """Test different conditions for 2s."""
    N = len(grid[0])
    center = next(i for i, v in enumerate(grid[0]) if v != 0)

    output = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            manhattan = abs(r - center) + abs(c - center)

            if r == center and c == center:
                output[r][c] = 0
            elif manhattan < 2 * center:
                output[r][c] = 1
            elif manhattan == 2 * center:
                # When is it 2?
                # Test several conditions
                diff_row = abs(r - center)
                diff_col = abs(c - center)

                # Condition A: diff_row * diff_col == center - 1
                # Condition B: (r - center) * (c - center) >= center
                # Condition C: max(diff_row, diff_col) + min(diff_row, diff_col) == dist

                if diff_row == diff_col and diff_row > 0:
                    output[r][c] = 2
                else:
                    output[r][c] = 1
            else:
                output[r][c] = 0

    return output

