def transform_diamond_v8(grid):
    """Final transform: 2s where on X-diagonal AND both diffs > 0 AND both < center."""
    N = len(grid[0])
    center = next(i for i, v in enumerate(grid[0]) if v != 0)

    output = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            if r == center and c == center:
                output[r][c] = 0
            else:
                manhattan = abs(r - center) + abs(c - center)

                if manhattan < 2 * center:
                    output[r][c] = 1
                elif manhattan == 2 * center:
                    # Boundary
                    diff_row = abs(r - center)
                    diff_col = abs(c - center)

                    # 2 when both diffs are > 0 and < center (true diagonal interior)
                    # 1 when one diff is 0 (edges of diamond)
                    if diff_row == 0 or diff_col == 0:
                        output[r][c] = 1
                    else:
                        output[r][c] = 2
                else:
                    output[r][c] = 0

    return output

