import json

def transform_diamond_final_correct(grid):
    """Final correct transform."""
    N = len(grid[0])
    center = next(i for i, v in enumerate(grid[0]) if v != 0)

    output = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            manhattan = abs(r - center) + abs(c - center)

            if r == center and c == center:
                output[r][c] = 0
            elif manhattan < 2 * center:
                # Interior (excluding center)
                output[r][c] = 1
            elif manhattan == 2 * center:
                # Boundary - corners are 1, others are 2
                diff_row = abs(r - center)
                diff_col = abs(c - center)
                if diff_row == 0 or diff_col == 0:
                    # Corner boundary
                    output[r][c] = 1
                else:
                    # Other boundary
                    output[r][c] = 2
            else:
                # Outside diamond
                output[r][c] = 0

    return output

