    N = len(grid[0])
    center = next(i for i, v in enumerate(grid[0]) if v != 0)

    output = [[0] * N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            manhattan = abs(r - center) + abs(c - center)

            if manhattan == 0:
                output[r][c] = 0
            elif manhattan < 2 * center:
