                diff_row = abs(r - center)
                diff_col = abs(c - center)
                if diff_row == 0 or diff_col == 0:
                    output[r][c] = 1
                else:
                    output[r][c] = 2
            else:  # manhattan > 2*center
                output[r][c] = 0

    return output

